1: # Unit Testing Guide
2: 
3: ## Overview
4: 
5: Unit tests test individual functions, methods, or classes in isolation. They are the foundation of a well-tested Flutter app, providing fast feedback and high maintainability.
6: 
7: ## When to Write Unit Tests
8: 
9: - Testing business logic functions
10: - Validating data transformations
11: - Testing state management logic (Bloc, Provider, Riverpod)
12: - Mocking external services/API calls
13: - Testing utility functions and helpers
14: 
15: ## Test Structure
16: 
17: ### Basic Test
18: 
19: ```dart
20: import 'package:test/test.dart';
21: 
22: void main() {
23:   test('description', () {
24:     // Arrange
25:     final subject = MyClass();
26:     
27:     // Act
28:     final result = subject.myMethod();
29:     
30:     // Assert
31:     expect(result, expectedValue);
32:   });
33: }
34: ```
35: 
36: ### Group Tests
37: 
38: ```dart
39: import 'package:test/test.dart';
40: 
41: void main() {
42:   group('Counter', () {
43:     late Counter counter;
44:     
45:     setUp(() {
46:       counter = Counter();
47:     });
48:     
49:     test('value starts at 0', () {
50:       expect(counter.value, 0);
51:     });
52:     
53:     test('increment increases value', () {
54:       counter.increment();
55:       expect(counter.value, 1);
56:     });
57:     
58:     tearDown(() {
59:       counter.dispose();
60:     });
61:   });
62: }
63: ```
64: 
65: ## Testing Patterns
66: 
67: ### Testing Pure Functions
68: 
69: ```dart
70: // Function to test
71: int add(int a, int b) => a + b;
72: 
73: // Test
74: test('add returns sum of two numbers', () {
75:   expect(add(2, 3), 5);
76:   expect(add(-1, 1), 0);
77: });
78: ```
79: 
80: ### Testing State Changes
81: 
82: ```dart
83: class Counter {
84:   int _value = 0;
85:   int get value => _value;
86:   
87:   void increment() => _value++;
88:   void decrement() => _value--;
89:   void reset() => _value = 0;
90: }
91: 
92: // Tests
93: group('Counter state changes', () {
94:   late Counter counter;
95:   
96:   setUp(() => counter = Counter());
97:   
98:   test('initial value is 0', () {
99:     expect(counter.value, 0);
100:   });
101:   
102:   test('increment increases value by 1', () {
103:     counter.increment();
104:     expect(counter.value, 1);
105:   });
106:   
107:   test('decrement decreases value by 1', () {
108:     counter.decrement();
109:     expect(counter.value, -1);
110:   });
111:   
112:   test('multiple increments work correctly', () {
113:     counter.increment();
114:     counter.increment();
115:     counter.increment();
116:     expect(counter.value, 3);
117:   });
118: });
119: ```
120: 
121: ### Testing Async Operations
122: 
123: ```dart
124: class DataService {
125:   Future<String> fetchData() async {
126:     await Future.delayed(const Duration(seconds: 1));
127:     return 'data';
128:   }
129: }
130: 
131: // Test
132: test('fetchData returns data after delay', () async {
133:   final service = DataService();
134:   final result = await service.fetchData();
135:   expect(result, 'data');
136: });
137: ```
138: 
139: ### Testing Streams
140: 
141: ```dart
142: class CounterStream {
143:   final _controller = StreamController<int>();
144:   Stream<int> get stream => _controller.stream;
145:   
146:   void increment() => _controller.sink.add(1);
147:   void dispose() => _controller.close();
148: }
149: 
150: // Test
151: test('stream emits values', () async {
152:   final counter = CounterStream();
153:   
154:   expectLater(
155:     counter.stream,
156:     emitsInOrder([1, 1, 1]),
157:   );
158:   
159:   counter.increment();
160:   counter.increment();
161:   counter.increment();

161:   counter.increment();
162:   
163:   await Future.delayed(const Duration(milliseconds: 100));
164:   counter.dispose();
165: });
166: ```
167: 
168: ## Matchers
169: 
170: ### Common Matchers
171: 
172: ```dart
173: // Equality
174: expect(actual, equals(expected));
175: 
176: // Not equal
177: expect(actual, isNot(equals(expected)));
178: 
179: // Null checks
180: expect(value, isNull);
181: expect(value, isNotNull);
182: 
183: // Numeric comparisons
184: expect(5, greaterThan(3));
185: expect(5, lessThan(10));
186: expect(5, greaterThanOrEqualTo(5));
187: expect(5, lessThanOrEqualTo(5));
188: 
189: // Type checking
190: expect(obj, isA<String>());
191: expect(obj, isNot(isA<int>()));
192: 
193: // String matching
194: expect(text, contains('substring'));
195: expect(text, startsWith('prefix'));
196: expect(text, endsWith('suffix'));
197: expect(text, matches(RegExp(r'\d+')));
198: 
199: // Lists
200: expect(list, isEmpty);
201: expect(list, isNotEmpty);
202: expect(list, hasLength(3));
203: expect(list, contains(item));
204: expect(list, orderedEquals([1, 2, 3]));
205: ```
206: 
207: ### Custom Matchers
208: 
209: ```dart
210: import 'package:test/test.dart';
211: 
212: class HasLength extends Matcher {
213:   final int expectedLength;
214:   HasLength(this.expectedLength);
215:   
216:   @override
217:   bool matches(item, Map matchState) {
218:     return (item as List).length == expectedLength;
219:   }
220:   
221:   @override
222:   Description describe(Description description) {
223:     return description.add('has length $expectedLength');
224:   }
225: }
226: 
227: // Usage
228: test('list has custom length', () {
229:   final list = [1, 2, 3];
230:   expect(list, HasLength(3));
231: });
232: ```
233: 
234: ## Exception Testing
235: 
236: ```dart
237: class Calculator {
238:   int divide(int a, int b) {
239:     if (b == 0) throw ArgumentError('Cannot divide by zero');
240:     return a ~/ b;
241:   }
242: }
243: 
244: // Test
245: test('divide throws when dividing by zero', () {
246:   final calculator = Calculator();
247:   expect(
248:     () => calculator.divide(10, 0),
249:     throwsArgumentError,
250:   );
251: });
252: 
253: test('divide throws with specific message', () {
254:   final calculator = Calculator();
255:   expect(
256:     () => calculator.divide(10, 0),
257:     throwsA(isA<ArgumentError>()
258:       .having((e) => e.message, 'message', contains('zero'))),
259:   );
260: });

